<template>
  <div class="el-plus-input">
    <el-input v-bind="$attrs" v-on="$listeners" v-model="inputValue" />
    <div v-if="tip">
      <div v-if="toolTip" class="tooltip" :style="toolTipStyle">
        <el-tooltip :content="tip" placement="top">
          <i class="el-icon-question"></i>
        </el-tooltip>
      </div>
      <div class="tip" v-else>{{ tip }}</div>
    </div>
  </div>
</template>
<script>
export default {
  name: 'ElPlusInput',
  props: {
    value: {
      type: String,
      default: '',
    },
    tip: {
      type: String,
      default: '',
    },
    toolTip: {
      type: Boolean,
      default: false,
    },
    toolTipStyle: {
      type: Object,
      default: () => {
        return {}
      },
    },
  },
  computed: {
    inputValue: {
      get() {
        return this.value
      },
      set(val) {
        this.$emit('input', val)
      },
    },
  },
  watch: {
    value(val) {
      this.inputValue = val
    },
  },
}
</script>
<style lang="less" scoped>
.el-plus-input {
  position: relative;
  display: inline-block;
  .tip {
    position: absolute;
    margin-top: 5px;
    font-size: 12px;
    color: #888;
    line-height: 1;
    padding: 4px 0;
  }
  .tooltip {
    position: absolute;
    right: 0px;
    font-size: 12px;
    color: #888;
    top: 0px;
  }
}
</style>